import { createRequire } from 'node:module'
import crypto from 'node:crypto'

const require = createRequire(import.meta.url)

export function isRedisEnabled() {
  return Boolean(String(process.env.REDIS_URL || '').trim())
}

const KEY_PREFIX = 'writing-assistant:v2:'
const SESSION_VERSION = 2

let clientPromise = null

function getClient() {
  if (!isRedisEnabled()) return null
  if (!clientPromise) {
    const redisUrl = String(process.env.REDIS_URL).trim()
    const Redis = require('ioredis')
    clientPromise = new Redis(redisUrl, {
      lazyConnect: false,
      maxRetriesPerRequest: 2,
      enableReadyCheck: true,
      reconnectOnError(err) {
        return err?.message?.includes('READONLY') || false
      },
    })
    clientPromise.on('error', (error) => {
      // ioredis 默认会在后台重连；这里只记日志，避免未捕获事件杀进程。
      if (process.env.NODE_ENV !== 'test') console.error('[chat-memory] redis error:', error.message)
    })
  }
  return clientPromise
}

function emptyRequirements() {
  return { type: '', genre: '', style: '', premise: '', platform: '', title: '' }
}

/**
 * 把任意来源的会话对象归一化为内部会话形状，保证字段与默认值齐全。
 * 镜像 server/index.mjs 的 createWritingSession / appendWritingMessage 不变量。
 */
export function normalizeWritingSession(raw, userId) {
  if (!raw || typeof raw !== 'object') return null
  const session = {
    id: typeof raw.id === 'string' && raw.id ? raw.id : crypto.randomUUID(),
    userId: userId || raw.userId || null,
    phase: ['collecting_requirements', 'awaiting_confirmation', 'writing'].includes(raw.phase) ? raw.phase : 'collecting_requirements',
    messages: Array.isArray(raw.messages)
      ? raw.messages
          .filter((item) => item && typeof item === 'object' && typeof item.text === 'string')
          .map((item) => ({
            id: typeof item.id === 'string' ? item.id : crypto.randomUUID(),
            role: item.role === 'assistant' ? 'assistant' : 'user',
            text: String(item.text).slice(0, 4000),
            createdAt: typeof item.createdAt === 'string' ? item.createdAt : null,
          }))
          .slice(-20)
      : [],
    requirements: { ...emptyRequirements(), ...(raw.requirements && typeof raw.requirements === 'object' ? raw.requirements : {}) },
    proposal: raw.proposal && typeof raw.proposal === 'object' ? raw.proposal : null,
    selectedSkill: typeof raw.selectedSkill === 'string' ? raw.selectedSkill : null,
    questions: Array.isArray(raw.questions) ? raw.questions.filter(Boolean) : [],
    lastResult: raw.lastResult ?? null,
    projectId: typeof raw.projectId === 'string' ? raw.projectId : null,
    createdAt: typeof raw.createdAt === 'string' ? raw.createdAt : null,
    updatedAt: typeof raw.updatedAt === 'string' ? raw.updatedAt : raw.createdAt || null,
  }
  return session
}

export function serializeSession(session) {
  return JSON.stringify({ v: SESSION_VERSION, session })
}

export async function getSession(userId) {
  if (!isRedisEnabled()) return null
  const client = getClient()
  if (!client) return null
  try {
    const raw = await client.get(`${KEY_PREFIX}${userId}`)
    if (!raw) return null
    const parsed = JSON.parse(raw)
    return normalizeWritingSession(parsed?.session ?? parsed, userId)
  } catch (error) {
    if (process.env.NODE_ENV !== 'test') console.error('[chat-memory] getSession failed:', error.message)
    return null
  }
}

export async function setSession(userId, session) {
  if (!isRedisEnabled()) return false
  const client = getClient()
  if (!client) return false
  try {
    const normalized = normalizeWritingSession(session, userId)
    await client.set(`${KEY_PREFIX}${userId}`, serializeSession(normalized))
    return true
  } catch (error) {
    if (process.env.NODE_ENV !== 'test') console.error('[chat-memory] setSession failed:', error.message)
    return false
  }
}

export async function deleteSession(userId) {
  if (!isRedisEnabled()) return false
  const client = getClient()
  if (!client) return false
  try {
    await client.del(`${KEY_PREFIX}${userId}`)
    return true
  } catch (error) {
    if (process.env.NODE_ENV !== 'test') console.error('[chat-memory] deleteSession failed:', error.message)
    return false
  }
}

export async function closeClient() {
  if (!clientPromise) return
  try {
    await clientPromise.quit()
  } catch {
    // 忽略关闭错误
  }
  clientPromise = null
}

import { readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const defaultJsonFile = process.env.STORY_DATA_FILE || path.join(rootDir, 'server', 'data', 'db.json')
const action = process.argv[2] || 'status'

if (action !== 'status' && !String(process.env.DATABASE_URL || '').trim()) {
  console.error('DATABASE_URL is required for database migration commands')
  process.exit(1)
}

const { closeStore, loadDb, replaceDb, storeInfo } = await import('./store.mjs')

try {
  if (action === 'import') {
    const source = process.argv[3] || defaultJsonFile
    const parsed = JSON.parse(await readFile(source, 'utf8'))
    await replaceDb(parsed)
    console.log(`Imported JSON data from ${source} into ${storeInfo().backend}.`)
  } else if (action === 'export') {
    const target = process.argv[3] || defaultJsonFile
    const db = await loadDb()
    await writeFile(target, JSON.stringify(db, null, 2), 'utf8')
    console.log(`Exported ${storeInfo().backend} data to ${target}.`)
  } else if (action === 'status') {
    const db = await loadDb()
    console.log(JSON.stringify({ ...storeInfo(), users: db.users.length, projects: db.projects.length }, null, 2))
  } else {
    console.error('Usage: node server/db-cli.mjs <status|import|export> [file]')
    process.exitCode = 1
  }
} finally {
  await closeStore()
}

import crypto from 'node:crypto'
import { promisify } from 'node:util'
import { jwtVerify, SignJWT } from 'jose'

const scrypt = promisify(crypto.scrypt)
const issuer = 'story-studio-api'
const audience = 'story-studio-client'

function boundedPositiveIntegerEnv(name, fallback, maximum) {
  const value = Number(process.env[name])
  return Number.isInteger(value) && value > 0 ? Math.min(value, maximum) : fallback
}

const accessTtlSeconds = boundedPositiveIntegerEnv('ACCESS_TOKEN_TTL_MINUTES', 60, 24 * 60) * 60
const refreshTtlMs = boundedPositiveIntegerEnv('REFRESH_SESSION_DAYS', 90, 365) * 24 * 60 * 60 * 1000
const passwordResetTtlMs = boundedPositiveIntegerEnv('PASSWORD_RESET_TOKEN_TTL_MINUTES', 30, 24 * 60) * 60 * 1000
const emailVerificationTtlMs = boundedPositiveIntegerEnv('EMAIL_VERIFICATION_CODE_TTL_MINUTES', 10, 60) * 60 * 1000
const configuredSecret = process.env.AUTH_SECRET || 'local-dev-only-change-this-story-studio-secret'
const signingKey = new TextEncoder().encode(configuredSecret)

export const usesDefaultSecret = !process.env.AUTH_SECRET
export const authSessionConfig = Object.freeze({
  accessTtlSeconds,
  refreshTtlMs,
  passwordResetTtlMs,
  emailVerificationTtlMs,
})

export async function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString('base64url')
  const derivedKey = await scrypt(password, salt, 64)
  return `scrypt$${salt}$${Buffer.from(derivedKey).toString('base64url')}`
}

export async function verifyPassword(password, encodedHash) {
  const [algorithm, salt, storedKey] = String(encodedHash || '').split('$')
  if (algorithm !== 'scrypt' || !salt || !storedKey) return false
  const stored = Buffer.from(storedKey, 'base64url')
  const derived = Buffer.from(await scrypt(password, salt, stored.length))
  return stored.length === derived.length && crypto.timingSafeEqual(stored, derived)
}

export async function createAccessToken(user) {
  return new SignJWT({ name: user.name, email: user.email, authVersion: Number(user.authVersion) || 0 })
    .setProtectedHeader({ alg: 'HS256', typ: 'JWT' })
    .setIssuer(issuer)
    .setAudience(audience)
    .setSubject(user.id)
    .setIssuedAt()
    .setExpirationTime(Math.floor(Date.now() / 1000) + accessTtlSeconds)
    .sign(signingKey)
}

export async function verifyAccessToken(token) {
  const result = await jwtVerify(token, signingKey, { issuer, audience, algorithms: ['HS256'] })
  return result.payload
}

export function createRefreshSession(userId, metadata = {}) {
  const token = crypto.randomBytes(48).toString('base64url')
  return {
    token,
    session: {
      id: crypto.randomUUID(),
      userId,
      tokenHash: hashRefreshToken(token),
      createdAt: new Date().toISOString(),
      expiresAt: new Date(Date.now() + refreshTtlMs).toISOString(),
      userAgent: String(metadata.userAgent || '').slice(0, 300),
    },
  }
}

export function hashRefreshToken(token) {
  return crypto.createHash('sha256').update(String(token)).digest('hex')
}

export function createPasswordResetToken(userId) {
  const token = crypto.randomBytes(32).toString('base64url')
  return {
    token,
    record: {
      id: crypto.randomUUID(),
      userId,
      tokenHash: hashPasswordResetToken(token),
      createdAt: new Date().toISOString(),
      expiresAt: new Date(Date.now() + passwordResetTtlMs).toISOString(),
    },
  }
}

export function hashPasswordResetToken(token) {
  return crypto.createHash('sha256').update(String(token)).digest('hex')
}

export function createEmailVerificationCode(email) {
  const code = String(crypto.randomInt(0, 1_000_000)).padStart(6, '0')
  return {
    code,
    record: {
      id: crypto.randomUUID(),
      email,
      codeHash: hashEmailVerificationCode(email, code),
      attempts: 0,
      createdAt: new Date().toISOString(),
      expiresAt: new Date(Date.now() + emailVerificationTtlMs).toISOString(),
    },
  }
}

export function hashEmailVerificationCode(email, code) {
  return crypto.createHmac('sha256', configuredSecret)
    .update(`${String(email).toLowerCase()}\0${String(code)}`)
    .digest('hex')
}

export function verifyEmailVerificationCode(email, code, expectedHash) {
  const expected = Buffer.from(String(expectedHash || ''), 'hex')
  const actual = Buffer.from(hashEmailVerificationCode(email, code), 'hex')
  return expected.length === actual.length && crypto.timingSafeEqual(expected, actual)
}

const encryptionKey = crypto.createHash('sha256').update(configuredSecret).digest()

export function encryptSecret(plaintext) {
  if (!plaintext) return null
  const iv = crypto.randomBytes(12)
  const cipher = crypto.createCipheriv('aes-256-gcm', encryptionKey, iv)
  const encrypted = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()])
  const tag = cipher.getAuthTag()
  return `gcm$${iv.toString('base64url')}$${tag.toString('base64url')}$${encrypted.toString('base64url')}`
}

export function decryptSecret(encoded) {
  if (!encoded) return null
  const parts = String(encoded).split('$')
  if (parts.length !== 4 || parts[0] !== 'gcm') return null
  const iv = Buffer.from(parts[1], 'base64url')
  const tag = Buffer.from(parts[2], 'base64url')
  const data = Buffer.from(parts[3], 'base64url')
  const decipher = crypto.createDecipheriv('aes-256-gcm', encryptionKey, iv)
  decipher.setAuthTag(tag)
  try {
    return Buffer.concat([decipher.update(data), decipher.final()]).toString('utf8')
  } catch {
    return null
  }
}

export function maskKey(key) {
  if (!key) return null
  const str = String(key)
  if (str.length <= 8) return '****'
  return `${str.slice(0, 3)}${'*'.repeat(Math.min(str.length - 7, 20))}${str.slice(-4)}`
}

export function publicUser(user) {
  return { id: user.id, name: user.name, email: user.email, createdAt: user.createdAt }
}

export const refreshCookie = {
  name: 'story_refresh',
  maxAge: refreshTtlMs,
}

