import test from 'node:test'
import assert from 'node:assert/strict'
import {
  normalizeWritingSession,
  serializeSession,
  getSession,
  setSession,
  deleteSession,
  closeClient,
} from './chat-memory.mjs'

const REDIS_TEST_URL = process.env.REDIS_TEST_URL || ''

test('normalizeWritingSession fills defaults and caps messages', () => {
  const normalized = normalizeWritingSession({ id: 's1', phase: 'weird', messages: [{ role: 'user', text: 'a' }, { text: 'b' }] }, 'u1')
  assert.equal(normalized.phase, 'collecting_requirements')
  assert.equal(normalized.userId, 'u1')
  assert.equal(normalized.messages.length, 2)
  assert.equal(normalized.messages[0].role, 'user')
  assert.equal(normalized.messages[1].role, 'user')
  assert.deepEqual(normalized.requirements, { type: '', genre: '', style: '', premise: '', platform: '', title: '' })
  assert.equal(normalized.projectId, null)
})

test('normalizeWritingSession caps to 20 messages and clamps text', () => {
  const messages = Array.from({ length: 25 }, (_, i) => ({ id: `m${i}`, role: 'user', text: String(i), createdAt: 't' }))
  const normalized = normalizeWritingSession({ id: 's2', messages }, 'u2')
  assert.equal(normalized.messages.length, 20)
  assert.equal(normalized.messages[0].text, '5')
})

test('serializeSession round-trips through normalizeWritingSession', () => {
  const session = { id: 's3', userId: 'u3', phase: 'awaiting_confirmation', messages: [{ id: 'm', role: 'assistant', text: 'hi', createdAt: 't' }], requirements: { type: '短篇' }, proposal: { title: 'X' }, projectId: 'p1' }
  const parsed = JSON.parse(serializeSession(session))
  const restored = normalizeWritingSession(parsed.session, 'u3')
  assert.equal(restored.phase, 'awaiting_confirmation')
  assert.equal(restored.projectId, 'p1')
  assert.equal(restored.proposal.title, 'X')
})

test('normalizeWritingSession returns null for invalid input', () => {
  assert.equal(normalizeWritingSession(null, 'u'), null)
  assert.equal(normalizeWritingSession('nope', 'u'), null)
})

const redisIt = REDIS_TEST_URL ? test : test.skip

redisIt('setSession/getSession/deleteSession round-trip against live Redis', async () => {
  process.env.REDIS_URL = REDIS_TEST_URL
  const session = { id: 'live-1', userId: 'live-user', phase: 'collecting_requirements', messages: [{ id: 'm1', role: 'user', text: '你好', createdAt: 'now' }] }
  await setSession('live-user', session)
  const fetched = await getSession('live-user')
  assert.equal(fetched.id, 'live-1')
  assert.equal(fetched.messages[0].text, '你好')
  await deleteSession('live-user')
  assert.equal(await getSession('live-user'), null)
  await closeClient()
})

import assert from 'node:assert/strict'
import { spawn } from 'node:child_process'
import { mkdtemp, rm } from 'node:fs/promises'
import os from 'node:os'
import path from 'node:path'

const tempDir = await mkdtemp(path.join(os.tmpdir(), 'story-registration-'))
const child = spawn(process.execPath, ['server/index.mjs'], {
  cwd: path.join(import.meta.dirname, '..'),
  env: {
    ...process.env,
    NODE_ENV: 'test', PORT: '0', HOST: '127.0.0.1', AUTH_SECRET: 'registration-test-secret-with-enough-entropy',
    STORY_DATA_FILE: path.join(tempDir, 'db.json'), AI_TASK_QUEUE_ENABLED: 'false',
    REGISTRATION_MODE: 'owner-only', ALLOW_SHARED_MODEL_KEY: 'false',
    EMAIL_PROVIDER: 'test', EMAIL_VERIFICATION_EXPOSE_CODE: 'true',
  },
  stdio: ['ignore', 'pipe', 'pipe'],
})

try {
  const baseUrl = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('API startup timeout')), 5_000)
    child.stdout.on('data', (chunk) => {
      const match = chunk.toString().match(/Story API listening on (http:\/\/[^\s]+)/)
      if (match) {
        clearTimeout(timeout)
        resolve(match[1])
      }
    })
    child.stderr.on('data', (chunk) => reject(new Error(chunk.toString())))
    child.on('exit', (code) => reject(new Error(`API exited early: ${code}`)))
  })
  const requestCode = async (email) => {
    const response = await fetch(`${baseUrl}/api/auth/register/code`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ email }),
    })
    return { response, payload: await response.json() }
  }
  const register = (name, email, verificationCode) => fetch(`${baseUrl}/api/auth/register`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ name, email, password: 'password123', verificationCode }),
  })
  const ownerCode = await requestCode('owner@example.com')
  assert.equal(ownerCode.response.status, 202)
  assert.equal((await register('站长', 'owner@example.com', ownerCode.payload.verificationCode)).status, 201)
  const closedCode = await requestCode('writer@example.com')
  assert.equal(closedCode.response.status, 403)
  const second = await register('其他作者', 'writer@example.com', '000000')
  assert.equal(second.status, 403)
  assert.equal((await second.json()).error, '当前站点未开放注册')
  console.log('Registration mode test passed: owner-only closes after the first account')
} finally {
  if (child.exitCode === null) {
    child.kill('SIGTERM')
    await new Promise((resolve) => child.once('exit', resolve))
  }
  await rm(tempDir, { recursive: true, force: true })
}

import { mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { applyStoryArtifacts } from './story-artifacts.mjs'
import { storeInfo } from './store.mjs'
import { chapterStoryFilePath, readStoryFileForAgent, storyFilePath } from './writing-context.mjs'

// 桌面端/本地模式专属：把作品的虚拟「作品文件」物化为真实目录，供本地命令/Skill 脚本操作；
// 任务结束后再把磁盘改动回收进数据库（applyStoryArtifacts 负责章节正文与资料的归位）。
const TEXT_EXTENSIONS = new Set(['.md', '.markdown', '.txt', '.json', '.yaml', '.yml', '.toml'])
const MAX_IMPORT_FILES = 400
const MAX_IMPORT_CHARS = 50_000

export function projectWorkspaceDir(projectId) {
  const dataFile = storeInfo().dataFile
  if (!dataFile) return null
  const safeId = String(projectId || '').replace(/[^\w-]/g, '_')
  if (!safeId) return null
  return path.join(path.dirname(dataFile), 'workspace', `project-${safeId}`)
}

function resolveInside(rootDir, relativePath) {
  const normalized = String(relativePath || '').replaceAll('\\', '/').trim()
  if (!normalized || normalized.startsWith('/') || /^[A-Za-z]:\//.test(normalized)) return null
  const parts = normalized.split('/').filter(Boolean)
  if (!parts.length || parts.some((part) => part === '.' || part === '..' || part.includes('\0'))) return null
  const resolved = path.resolve(rootDir, ...parts)
  const relative = path.relative(rootDir, resolved)
  if (relative.startsWith('..') || path.isAbsolute(relative)) return null
  return resolved
}

async function listWorkspaceFiles(rootDir) {
  const files = []
  const walk = async (dir) => {
    if (files.length >= MAX_IMPORT_FILES) return
    const entries = await readdir(dir, { withFileTypes: true }).catch(() => [])
    for (const entry of entries) {
      if (files.length >= MAX_IMPORT_FILES) return
      const full = path.join(dir, entry.name)
      if (entry.isDirectory()) await walk(full)
      else if (entry.isFile() && TEXT_EXTENSIONS.has(path.extname(entry.name).toLowerCase())) files.push(full)
    }
  }
  await walk(rootDir)
  return files
}

export function collectProjectFiles(db, userId, projectId) {
  const files = new Map()
  const project = db.projects?.find((item) => item.id === projectId && item.userId === userId)
  if (!project) return files
  const chapters = db.chapters?.[projectId] || []
  for (const chapter of chapters) {
    const relPath = chapterStoryFilePath(chapter)
    if (!relPath) continue
    files.set(relPath, String(db.drafts?.[projectId]?.[String(chapter.id)] || '').replace(/\r\n?/g, '\n'))
  }
  for (const idea of db.ideas || []) {
    if (idea.userId !== userId || idea.projectId !== projectId) continue
    const relPath = storyFilePath(idea)
    if (!relPath || files.has(relPath)) continue
    files.set(relPath, String(idea.body || '').replace(/\r\n?/g, '\n'))
  }
  return files
}

export async function materializeProjectWorkspace(db, userId, projectId, workspaceDir) {
  await rm(workspaceDir, { recursive: true, force: true })
  await mkdir(workspaceDir, { recursive: true })
  let written = 0
  for (const [relPath, content] of collectProjectFiles(db, userId, projectId)) {
    const target = resolveInside(workspaceDir, relPath)
    if (!target) continue
    await mkdir(path.dirname(target), { recursive: true })
    await writeFile(target, content, 'utf8')
    written += 1
  }
  return written
}

export async function writeWorkspaceFile(workspaceDir, relPath, content) {
  const target = resolveInside(workspaceDir, relPath)
  if (!target) return false
  await mkdir(path.dirname(target), { recursive: true })
  await writeFile(target, String(content ?? '').replace(/\r\n?/g, '\n'), 'utf8')
  return true
}

export function importWorkspaceChangesToState(db, userId, projectId, workspaceDir, diskFiles) {
  const documents = []
  for (const [absolutePath, content] of diskFiles) {
    if (!content.trim() || content.length > MAX_IMPORT_CHARS) continue
    const relPath = path.relative(workspaceDir, absolutePath).split(path.sep).join('/')
    const existing = readStoryFileForAgent(db, userId, projectId, relPath)
    if (existing && existing.content === content.trim()) continue
    documents.push({ path: relPath, content })
  }
  if (!documents.length) return { applied: false, imported: 0 }
  const application = applyStoryArtifacts(db, { userId, projectId, artifacts: { documents } })
  return { applied: application.applied, imported: application.documents || documents.length }
}

export async function importWorkspaceChanges(db, userId, projectId, workspaceDir) {
  const files = await listWorkspaceFiles(workspaceDir)
  const diskFiles = new Map()
  for (const absolutePath of files) {
    const content = await readFile(absolutePath, 'utf8').catch(() => null)
    if (typeof content === 'string') diskFiles.set(absolutePath, content.replace(/\r\n?/g, '\n'))
  }
  return importWorkspaceChangesToState(db, userId, projectId, workspaceDir, diskFiles)
}

