33	fn main() {
34	    tauri::Builder::default()
35	        .plugin(tauri_plugin_single_instance::init(|_app, _args, _cwd| {
36	            // 单实例：重复启动时聚焦已有窗口即可
37	        }))
38	        .plugin(tauri_plugin_shell::init())
39	        .setup(|app| {
40	            let handle = app.handle().clone();
41	            tauri::async_runtime::spawn(async move {
42	                if let Err(error) = boot(&handle).await {
