48	        .build(tauri::generate_context!())
49	        .expect("failed to build tauri application")
50	        .run(|_app, event| {
51	            if matches!(event, RunEvent::Exit) {
52	                if let Some(mut proc) = SERVER.lock().unwrap().take() {
53	                    let _ = proc.child.kill();
54	                }
55	            }
