59	/// 异步启动本地 Bun 服务并创建主窗口。
60	async fn boot(app: &tauri::AppHandle) -> Result<(), Box<dyn std::error::Error>> {
61	    let url = if tauri::is_dev() {
62	        // 开发模式：`bun run desktop:api` 已经在 127.0.0.1:8787 监听
63	        wait_reachable(DEV_URL, 60).await?;
64	        format!("http://{DEV_URL}")
65	    } else {
66	        spawn_local_server(app).await?
67	    };
68	
69	    create_main_window(app, &url)?;
70	    Ok(())
71	}
