73	/// 生产模式：以本地模式拉起随包 Bun sidecar。
74	async fn spawn_local_server(app: &tauri::AppHandle) -> Result<String, Box<dyn std::error::Error>> {
75	    let data_dir = app.path().app_data_dir()?;
76	    fs::create_dir_all(&data_dir)?;
77	    let resource_dir = app.path().resource_dir()?;
78	
