117	/// 在数据目录读写持久化 AUTH_SECRET，保证本地加密的模型 Key 重启后仍可解密。
118	fn ensure_local_auth_secret(data_dir: &PathBuf) -> Result<String, Box<dyn std::error::Error>> {
119	    let secret_file = data_dir.join("auth-secret");
120	    if let Ok(raw) = fs::read_to_string(&secret_file) {
121	        let trimmed = raw.trim().to_string();
122	        if trimmed.len() >= 32 {
123	            return Ok(trimmed);
124	        }
125	    }
126	    let mut bytes = [0u8; 48];
