test('agent payload enforces a bounded permission policy', () => {
  const payload = enrichStoryAgentPayload(db, 'user-1', {
    project_id: project.id,
    chapter_id: 15,
    attached_files: [{ name: '灯塔', reference: { type: 'idea', id: 'idea-1' } }],
